const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Ingeniero White port location and 10 km radius
  const portCoords = [-62.3, -38.8]; // [longitude, latitude]
  const geometry = ee.Geometry.Point(portCoords).buffer(10000); // 10 km radius in meters

  // Define dates
  const date1 = '2025-01-30';
  const date2 = '2025-03-11';

  // Function to process inundation for a given date
  async function analyzeInundation(dateStr) {
    const startDate = dateStr;
    const endDate = ee.Date(dateStr).advance(1, 'day');

    // Get Sentinel-2 collection
    let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(geometry)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 50));

    const colSize = col.size().getInfo();
    console.log(`Date ${dateStr}: ${colSize} images found`);

    if (colSize === 0) {
      return null; // No data
    }

    // Composite best image (least cloudy)
    const img = col.sort('CLOUDY_PIXEL_PERCENTAGE').first();

    // Calculate NDWI for water detection
    const ndwi = img.normalizedDifference(['B3', 'B8']); // Green and NIR

    // Mask clouds using SCL band
    const cloudMask = img.select('SCL').neq(3).and(img.select('SCL').neq(8)).and(img.select('SCL').neq(9));
    const ndwiMasked = ndwi.updateMask(cloudMask);

    // Threshold for inundation (NDWI > 0.3 indicates water)
    const inundated = ndwiMasked.gt(0.3);

    // Count inundated pixels
    const pixelCount = inundated.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 10, // Sentinel-2 native resolution
      maxPixels: 1e9
    }).getInfo();

    const inundatedPixels = pixelCount.nd || 0;
    console.log(`Inundated pixels (${dateStr}): ${inundatedPixels}`);

    return inundatedPixels;
  }

  // Analyze both dates
  const pixels1 = await analyzeInundation(date1);
  const pixels2 = await analyzeInundation(date2);

  // Validate results
  if (pixels1 === null || pixels2 === null) {
    console.log('C1: Empty Collection (No images found for one or both dates)');
    return;
  }

  if (pixels1 === 0 && pixels2 === 0) {
    console.log(`Inundation Jan 30: 0, Mar 11: 0 pixels`);
    console.log('B: No increase detected (both dates show no inundation)');
    return;
  }

  if (pixels1 === undefined || pixels2 === undefined || isNaN(pixels1) || isNaN(pixels2)) {
    console.log('C3: Calculation Failure (Invalid pixel count)');
    return;
  }

  // Compare inundation areas
  console.log(`Inundation comparison:`);
  console.log(`Jan 30, 2025: ${pixels1} pixels`);
  console.log(`Mar 11, 2025: ${pixels2} pixels`);

  if (pixels2 > pixels1) {
    console.log('A: Yes - Inundation increased on March 11 compared to January 30');
  } else {
    console.log('B: No - Inundation did not increase or decreased on March 11');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
